export function parseProcessWithdrawalInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedProcessWithdrawalInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 14) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 14,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      keeper: getNextAccount(),
      userBundleAccountOwner: getNextAccount(),
      userTokenAccount: getNextAccount(),
      assetAddress: getNextAccount(),
      bundleAssetAccount: getNextAccount(),
      pendingBundleAssetAuthority: getNextAccount(),
      userBundleAccount: getNextAccount(),
      treasuryAccount: getNextAccount(),
      bundleAssetAuthority: getNextAccount(),
      bundleAccount: getNextAccount(),
      bundleTempData: getNextAccount(),
      oracleData: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getProcessWithdrawalInstructionDataDecoder().decode(instruction.data),
  };
}
